UPDATE usuarios SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';

UPDATE produtos SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day', atualizado_em = atualizado_em + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';

UPDATE produto_imagens SET criado_em = criado_em + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';

UPDATE movimentacoes SET data_hora = data_hora + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';

UPDATE vendas SET data_hora = data_hora + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day', cancelada_em = cancelada_em + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';

UPDATE alertas SET data_criacao = data_criacao + (CURRENT_DATE - DATE '2026-09-28') * INTERVAL '1 day';
